21	void timi_s32tos8(void *dp, Sint32 *lp, Sint32 c)
22	{
23	  Sint8 *cp=(Sint8 *)(dp);
24	  Sint32 l;
25	  while (c--)
26	    {
27	      l=(*lp++)>>(32-8-GUARD_BITS);
28	      if (l>127) l=127;
29	      else if (l<-128) l=-128;
30	      *cp++ = (Sint8) (l);
31	    }
32	}
33	
34	void timi_s32tou8(void *dp, Sint32 *lp, Sint32 c)
35	{
36	  Uint8 *cp=(Uint8 *)(dp);
37	  Sint32 l;
38	  while (c--)
